const fs = require("fs");
const {
  Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType,
  ImageRun, Table, TableRow, TableCell, WidthType, ShadingType,
  BorderStyle, LevelFormat, SectionType,
} = require("docx");

const media = (name) => fs.readFileSync(`/home/claude/work/build/media/${name}`);

function shot(name, caption, targetWidthIn = 3.1) {
  const widthPx = Math.round(targetWidthIn * 96);
  const heightPx = Math.round(widthPx * (1080 / 1920));
  return [
    new Paragraph({
      alignment: AlignmentType.CENTER,
      spacing: { before: 160, after: 60 },
      children: [
        new ImageRun({ type: "png", data: media(name), transformation: { width: widthPx, height: heightPx } }),
      ],
    }),
    new Paragraph({
      alignment: AlignmentType.CENTER,
      spacing: { after: 160 },
      children: [new TextRun({ text: caption, italics: true, size: 18 })],
    }),
  ];
}

function h2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    spacing: { before: 200, after: 100 },
    children: [new TextRun({ text, bold: true, size: 22 })],
  });
}
function h3(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    spacing: { before: 160, after: 80 },
    children: [new TextRun({ text, bold: true, italics: true, size: 21 })],
  });
}
function p(text, opts = {}) {
  return new Paragraph({
    spacing: { after: 120, line: 300 },
    alignment: opts.align || AlignmentType.JUSTIFIED,
    indent: opts.indent,
    children: Array.isArray(text) ? text : [new TextRun({ text, italics: opts.italics, bold: opts.bold, size: opts.size || 20 })],
  });
}
function bullet(text) {
  return new Paragraph({
    spacing: { after: 80, line: 300 },
    alignment: AlignmentType.JUSTIFIED,
    bullet: { level: 0 },
    children: [new TextRun({ text, size: 20 })],
  });
}
function ref(text) {
  return new Paragraph({
    spacing: { after: 120, line: 276 },
    alignment: AlignmentType.JUSTIFIED,
    indent: { left: 360, hanging: 360 },
    children: [new TextRun({ text, size: 20 })],
  });
}

function dataTable(rows) {
  const colWidths = [1600, 3200];
  const mk = (text, header) => new TableCell({
    width: { size: text.length && header !== undefined ? colWidths[0] : colWidths[1], type: WidthType.DXA },
    shading: header ? { type: ShadingType.CLEAR, fill: "D9D9D9" } : undefined,
    margins: { top: 40, bottom: 40, left: 60, right: 60 },
    children: [new Paragraph({ children: [new TextRun({ text, bold: header, size: 18 })] })],
  });
  const trs = rows.map((r, idx) => new TableRow({
    children: [
      new TableCell({ width: { size: colWidths[0], type: WidthType.DXA }, shading: idx === 0 ? { type: ShadingType.CLEAR, fill: "D9D9D9" } : undefined, margins: { top: 40, bottom: 40, left: 60, right: 60 }, children: [new Paragraph({ children: [new TextRun({ text: r[0], bold: idx === 0, size: 18 })] })] }),
      new TableCell({ width: { size: colWidths[1], type: WidthType.DXA }, shading: idx === 0 ? { type: ShadingType.CLEAR, fill: "D9D9D9" } : undefined, margins: { top: 40, bottom: 40, left: 60, right: 60 }, children: [new Paragraph({ children: [new TextRun({ text: r[1], bold: idx === 0, size: 18 })] })] }),
    ],
  }));
  return new Table({
    width: { size: 4800, type: WidthType.DXA },
    columnWidths: colWidths,
    rows: trs,
    borders: {
      top: { style: BorderStyle.SINGLE, size: 4, color: "888888" },
      bottom: { style: BorderStyle.SINGLE, size: 4, color: "888888" },
      left: { style: BorderStyle.SINGLE, size: 4, color: "888888" },
      right: { style: BorderStyle.SINGLE, size: 4, color: "888888" },
      insideHorizontal: { style: BorderStyle.SINGLE, size: 4, color: "888888" },
      insideVertical: { style: BorderStyle.SINGLE, size: 4, color: "888888" },
    },
  });
}

const PAGE_W = 11906, PAGE_H = 16838; // A4
const MARGIN = 1000;

const doc = new Document({
  sections: [
    // ===== SECTION 1: Title, authors, abstract (single column) =====
    {
      properties: {
        page: { size: { width: PAGE_W, height: PAGE_H }, margin: { top: MARGIN, bottom: MARGIN, left: MARGIN, right: MARGIN } },
      },
      children: [
        new Paragraph({
          alignment: AlignmentType.CENTER,
          spacing: { after: 120 },
          children: [new TextRun({ text: "PEMBANGUNAN SISTEM INFORMASI AKADEMIK BERBASIS WEB MENGGUNAKAN FRAMEWORK LARAVEL 10 (STUDI KASUS: MANAJEMEN DATA MAHASISWA, DOSEN, MATA KULIAH, DAN PERKULIAHAN)", bold: true, size: 30 })],
        }),
        new Paragraph({
          alignment: AlignmentType.CENTER,
          spacing: { before: 200, after: 40 },
          children: [new TextRun({ text: "Riska Putri Anggelina", bold: true, size: 22 })],
        }),
        new Paragraph({
          alignment: AlignmentType.CENTER,
          spacing: { after: 20 },
          children: [new TextRun({ text: "Program Studi Teknologi Informasi, Fakultas Sains dan Teknologi", size: 20 })],
        }),
        new Paragraph({
          alignment: AlignmentType.CENTER,
          spacing: { after: 20 },
          children: [new TextRun({ text: "Universitas PGRI Sumatera Barat", size: 20 })],
        }),
        new Paragraph({
          alignment: AlignmentType.CENTER,
          spacing: { after: 240 },
          children: [new TextRun({ text: "Email: riska@gmail.com", size: 20, italics: true })],
        }),

        new Paragraph({ spacing: { after: 60 }, children: [new TextRun({ text: "Abstrak", bold: true, size: 21 })] }),
        p("Pengelolaan data akademik yang dilakukan secara manual pada banyak institusi pendidikan masih menimbulkan berbagai kendala, seperti data yang tidak konsisten, sulit dicari, dan rawan kesalahan input. Penelitian ini bertujuan untuk membangun Sistem Informasi Akademik berbasis web dengan studi kasus pengelolaan data mahasiswa, dosen, mata kuliah, dan perkuliahan, dengan nama project RISKA-UAS. Sistem dikembangkan menggunakan framework Laravel 10 yang menerapkan arsitektur Model-View-Controller (MVC), didukung Laragon sebagai local development environment dan MySQL sebagai basis data. Metode pengembangan yang digunakan adalah model Waterfall, meliputi tahap analisis kebutuhan, perancangan basis data, implementasi kode program, hingga pengujian pada browser. Fitur autentikasi (login dan register) diimplementasikan menggunakan paket laravel/ui dengan dua pilihan scaffolding, yaitu Bootstrap dan React, serta asset front-end dikompilasi menggunakan Vite. Relasi antar tabel users, mahasiswas, dosens, matakuliahs, dan perkuliahans diterapkan melalui Eloquent ORM dengan relasi hasMany dan belongsTo. Hasil pengujian pada browser menunjukkan bahwa proses registrasi pengguna, penambahan data KRS, pengelolaan data dosen, serta dashboard ringkasan data akademik dapat berjalan sesuai rancangan. Penelitian ini menyimpulkan bahwa Laravel 10 dapat digunakan secara efektif untuk membangun sistem informasi akademik yang terstruktur, dengan proses migration yang memudahkan pengelolaan versi basis data.", { size: 19 }),
        new Paragraph({ spacing: { after: 160 }, children: [new TextRun({ text: "Kata Kunci: Sistem Informasi Akademik, Laravel, MVC, Basis Data, Waterfall", bold: true, italics: true, size: 19 })] }),

        new Paragraph({ spacing: { after: 60 }, children: [new TextRun({ text: "Abstract", bold: true, italics: true, size: 21 })] }),
        p("Manual academic data management in many educational institutions still causes various problems, such as inconsistent data, difficulty in searching, and input errors. This research aims to build a web-based Academic Information System with a case study of managing student, lecturer, course, and class enrollment data, under the project name RISKA-UAS. The system was developed using the Laravel 10 framework which implements the Model-View-Controller (MVC) architecture, supported by Laragon as a local development environment and MySQL as the database. The development method used is the Waterfall model, covering requirement analysis, database design, code implementation, and browser-based testing. Authentication features (login and register) were implemented using the laravel/ui package with two scaffolding options, Bootstrap and React, and front-end assets were compiled using Vite. Relationships between the users, mahasiswas, dosens, matakuliahs, and perkuliahans tables were implemented through Eloquent ORM with hasMany and belongsTo relations. Browser testing results show that the user registration process, adding KRS data, managing lecturer data, and the academic data summary dashboard run according to the design. This research concludes that Laravel 10 can be effectively used to build a well-structured academic information system, with a migration process that simplifies database version management.", { size: 19, italics: true }),
        new Paragraph({ spacing: { after: 100 }, children: [new TextRun({ text: "Keywords: Academic Information System, Laravel, MVC, Database, Waterfall", bold: true, italics: true, size: 19 })] }),
      ],
    },

    // ===== SECTION 2: Body in two columns =====
    {
      properties: {
        type: SectionType.CONTINUOUS,
        page: { size: { width: PAGE_W, height: PAGE_H }, margin: { top: MARGIN, bottom: MARGIN, left: MARGIN, right: MARGIN } },
        column: { count: 2, space: 420 },
      },
      children: [
        h2("1. PENDAHULUAN"),
        p("Perkembangan teknologi informasi menuntut institusi pendidikan memiliki sistem pengelolaan data akademik yang cepat, akurat, dan mudah diakses. Pencatatan data mahasiswa, dosen, mata kuliah, dan perkuliahan yang masih dilakukan secara manual sering menimbulkan kendala seperti data tidak konsisten, sulit dicari, dan rawan kesalahan input."),
        p("Berbagai penelitian terdahulu menunjukkan bahwa framework Laravel banyak digunakan untuk membangun sistem informasi akademik berbasis web karena kemudahan struktur MVC yang dimilikinya (Suwirmayanti et al., 2023; Sahrul et al., 2016). Struktur MVC memisahkan data, tampilan, dan logika aplikasi ke dalam komponen Model, View, dan Controller, sehingga proses pengembangan menjadi lebih cepat dan tersusun rapi (Mulianto & Sediyono, 2023). Selain itu, penerapan Laravel pada aplikasi pengolahan nilai akademik terbukti mempercepat proses pencatatan data serta membuat data lebih aman karena tersimpan dalam basis data terstruktur (Susanti & Junianto, 2017)."),
        p("Berdasarkan permasalahan tersebut, penelitian ini membangun sebuah Sistem Informasi Akademik berbasis web dengan project bernama RISKA-UAS menggunakan framework Laravel 10. Laravel dipilih karena menyediakan ORM Eloquent untuk mempermudah relasi antar tabel serta sistem migration yang memudahkan pengelolaan versi struktur basis data. Untuk mendukung pengembangan secara lokal, digunakan Laragon sebagai local server yang menyediakan Apache, MySQL, dan PHP dalam satu aplikasi, sehingga proses setup project dapat dilakukan dengan cepat melalui fitur Quick App."),
        p("Sistem ini juga dirancang dengan konsep pembedaan hak akses melalui kolom level pada tabel users, yang dihubungkan dengan data Mahasiswa dan Dosen, sehingga sistem berpotensi membedakan tampilan dan hak akses sesuai peran pengguna, sejalan dengan pendekatan autentikasi multi level user yang umum diterapkan pada sistem informasi akademik berbasis Laravel (Nursan & Akhyar, 2025)."),

        h2("2. METODE PENELITIAN"),
        p("Penelitian ini menggunakan model pengembangan perangkat lunak Waterfall, yang terdiri atas tahapan analisis kebutuhan, perancangan sistem, implementasi kode program, dan pengujian secara berurutan (Wahid, 2020). Model ini dipilih karena memberikan struktur tahapan yang jelas dan terorganisir bagi pengembangan aplikasi berskala kecil hingga menengah seperti pada studi kasus ini."),
        h3("2.1 Analisis Kebutuhan"),
        p("Kebutuhan fungsional sistem meliputi: instalasi dan konfigurasi lingkungan pengembangan melalui Laragon; login dan register melalui scaffolding laravel/ui; pengelolaan data (tambah, lihat, ubah, hapus) mahasiswa, dosen, mata kuliah, dan perkuliahan; serta relasi data perkuliahan yang menghubungkan mahasiswa, dosen, dan mata kuliah melalui Eloquent. Kebutuhan non-fungsional meliputi penggunaan Laravel 10 dan MySQL, lingkungan pengembangan lokal melalui Laragon, serta kompilasi asset front-end menggunakan Node.js dan Vite."),
        h3("2.2 Perancangan Basis Data"),
        p("Basis data dirancang dengan lima tabel utama, yaitu users, mahasiswas, dosens, matakuliahs, dan perkuliahans. Tabel perkuliahans berperan sebagai tabel relasi yang menghubungkan mahasiswa_id, dosen_id, dan matakuliah_id, ditambah user_id sebagai pencatat data dengan aturan onDelete('cascade'). Ringkasan struktur tabel users dan perkuliahans ditunjukkan pada Tabel 1 dan Tabel 2."),
        p([new TextRun({ text: "Tabel 1. Struktur Tabel Users", bold: true, size: 18 })]),
        dataTable([["Kolom", "Keterangan"], ["id", "Primary key"], ["level", "Jenis akun pengguna"], ["akun_mahasiswa_id", "Relasi ke mahasiswas"], ["akun_dosen_id", "Relasi ke dosens"]]),
        p([new TextRun({ text: "Tabel 2. Struktur Tabel Perkuliahans", bold: true, size: 18 })], { align: AlignmentType.LEFT }),
        dataTable([["Kolom", "Keterangan"], ["id", "Primary key"], ["mahasiswa_id", "Relasi ke mahasiswas"], ["dosen_id", "Relasi ke dosens"], ["matakuliah_id", "Relasi ke matakuliahs"], ["user_id", "Relasi ke users, cascade"]]),
        h3("2.3 Implementasi"),
        p("Tahap implementasi dilakukan pada lingkungan lokal menggunakan Laragon (Apache, MySQL, PHP 8.1) dan Visual Studio Code sebagai code editor. Project Laravel 10 dibuat melalui fitur Quick App dengan nama RISKA-UAS, dilanjutkan instalasi paket laravel/ui untuk scaffolding autentikasi (Bootstrap dan React), pembuatan Model, Migration, dan Controller untuk setiap entitas melalui perintah artisan make:model -mcr, serta kompilasi asset front-end menggunakan Vite."),
        h3("2.4 Pengujian"),
        p("Pengujian dilakukan secara fungsional pada tahap pengembangan, yaitu dengan menjalankan aplikasi melalui browser untuk memverifikasi bahwa proses register, penambahan data KRS, pengelolaan data dosen, dan dashboard menampilkan data sesuai dengan rancangan basis data. Pengujian lebih lanjut dengan metode blackbox testing yang lebih menyeluruh disarankan untuk pengembangan berikutnya."),

        h2("3. HASIL DAN PEMBAHASAN"),
        h3("3.1 Lingkungan Pengembangan dan Pembuatan Project"),
        p("Project RISKA-UAS dibuat melalui fitur Quick App pada Laragon setelah seluruh service (Apache, MySQL, PostgreSQL) dijalankan. Gambar 1 menunjukkan panel Laragon dengan service yang aktif, sedangkan Gambar 2 menunjukkan dialog Quick App dengan nama project RISKA-UAS."),
        ...shot("img_01.png", "Gambar 1. Panel Laragon menampilkan status service yang berjalan"),
        ...shot("img_02.png", "Gambar 2. Dialog Quick app dengan nama project RISKA-UAS"),
        p("Konfigurasi file .env kemudian diperiksa untuk memastikan APP_KEY dan DB_DATABASE (riska_db) sudah terisi dengan benar sebelum melanjutkan proses instalasi paket."),

        h3("3.2 Autentikasi dan Kompilasi Asset"),
        p("Fitur autentikasi diimplementasikan melalui paket laravel/ui dengan dua scaffolding, Bootstrap dan React. Proses generate scaffolding Bootstrap menghasilkan pesan Authentication scaffolding generated successfully sebagaimana pada Gambar 3."),
        ...shot("img_05.png", "Gambar 3. Scaffolding autentikasi Bootstrap berhasil dibuat"),
        p("Asset front-end selanjutnya dikompilasi menggunakan perintah npm run build yang menjalankan Vite untuk mem-bundling seluruh resource, termasuk Sass Bootstrap, ke dalam bundel produksi."),
        ...shot("img_08.png", "Gambar 4. Proses npm run build menjalankan Vite untuk kompilasi asset"),

        h3("3.3 Struktur Basis Data dan Kode Program"),
        p("Model, migration, dan controller untuk entitas Mahasiswa, Dosen, Matakuliah, dan Perkuliahan dibuat sekaligus melalui perintah php artisan make:model -mcr, dilanjutkan migration tambahan untuk kolom level pada users serta foreign key pada perkuliahans."),
        ...shot("img_09.png", "Gambar 5. Pembuatan Model, Migration, dan Controller untuk tiap entitas"),
        p("Seluruh migration dijalankan dengan php artisan migrate. Basis data riska_db dibuat secara otomatis dan seluruh tabel berhasil dieksekusi berstatus DONE, sebagaimana ditunjukkan pada Gambar 6."),
        ...shot("img_11.png", "Gambar 6. Perintah php artisan migrate berhasil dijalankan"),
        p("Struktur MVC diterapkan secara konsisten: Model Mahasiswa.php merepresentasikan struktur data dengan atribut fillable serta relasi hasMany() ke Perkuliahan, View create.blade.php pada modul Dosen menyediakan formulir input data, dan Controller MatakuliahController.php menjembatani permintaan pengguna dengan Model. Hal ini sejalan dengan konsep MVC yang memisahkan data, tampilan, dan logika aplikasi untuk mempercepat proses pengembangan (Mulianto & Sediyono, 2023)."),
        ...shot("img_15.png", "Gambar 7. Model Eloquent Mahasiswa.php pada folder app/Models"),

        h3("3.4 Hasil Uji Coba pada Browser"),
        p("Pengujian pada browser menunjukkan bahwa proses register pengguna baru berjalan sesuai rancangan, dengan data yang tersimpan pada tabel users."),
        ...shot("img_18.png", "Gambar 8. Halaman Register pada aplikasi RISKA-UAS"),
        p("Setelah login, pengguna admin dapat mengelola data melalui menu navigasi, termasuk menambahkan data KRS yang menghubungkan Mahasiswa dan Mata Kuliah, serta mengelola Data Dosen."),
        ...shot("img_19.png", "Gambar 9. Form Tambah Data KRS setelah login"),
        ...shot("img_20.png", "Gambar 10. Halaman Data Dosen pada aplikasi RISKA-UAS"),
        p("Dashboard menampilkan ringkasan jumlah data Mahasiswa, Dosen, Mata Kuliah, dan Pengguna secara real-time sesuai isi basis data, sekaligus menampilkan pesan selamat datang berdasarkan peran pengguna yang sedang login."),
        ...shot("img_21.png", "Gambar 11. Dashboard Sistem Akademik setelah admin login"),
        p("Hasil ini menunjukkan bahwa relasi antar tabel melalui Eloquent ORM serta pembedaan hak akses melalui kolom level pada tabel users dapat berfungsi sebagaimana dirancang, sejalan dengan pendekatan yang diterapkan pada penelitian sistem informasi akademik berbasis Laravel lainnya (Sahrul et al., 2016; Nursan & Akhyar, 2025)."),

        h2("4. KESIMPULAN"),
        bullet("Sistem Informasi Akademik berbasis web dengan project RISKA-UAS berhasil dibangun menggunakan framework Laravel 10, dengan Laragon sebagai local server dan Visual Studio Code sebagai editor."),
        bullet("Fitur autentikasi (login dan register) berhasil diimplementasikan melalui paket laravel/ui dengan scaffolding Bootstrap maupun React, dilengkapi kompilasi asset menggunakan Vite."),
        bullet("Struktur basis data dibangun melalui migration untuk lima tabel utama, lengkap dengan relasi foreign key dan aturan cascade delete, yang diimplementasikan melalui Eloquent ORM (hasMany dan belongsTo)."),
        bullet("Hasil uji coba pada browser menunjukkan bahwa proses register, penambahan data KRS, pengelolaan data dosen, dan dashboard ringkasan data berjalan sesuai dengan rancangan sistem."),
        bullet("Pengujian lebih lanjut dengan metode blackbox testing serta penambahan fitur CRUD lengkap pada seluruh modul disarankan untuk pengembangan berikutnya."),

        h2("DAFTAR PUSTAKA"),
        ref("Laragon. (2026). Laragon Documentation. https://laragon.org/docs"),
