namespace App\Http\Controllers;

use App\Models\Perkuliahan;
use App\Models\Mahasiswa;
use App\Models\Dosen;
use App\Models\Matakuliah;
use Illuminate\Http\Request;

class PerkuliahanController extends Controller
{
    /**
     * Menampilkan semua data perkuliahan beserta relasinya.
     */
    public function index()
    {
        $perkuliahan = Perkuliahan::with(['mahasiswa', 'dosen', 'matakuliah', 'user'])->get();

        return view('perkuliahan.index', compact('perkuliahan'));
    }

    /**
     * Menampilkan form tambah data perkuliahan.
     */
    public function create()
    {
        $mahasiswa  = Mahasiswa::all();
        $dosen      = Dosen::all();
        $matakuliah = Matakuliah::all();

        return view('perkuliahan.create', compact('mahasiswa', 'dosen', 'matakuliah'));
    }

    /**
     * Menyimpan data perkuliahan baru.
     */
    public function store(Request $request)
    {
        Perkuliahan::create([
            'mahasiswa_id'  => $request->mahasiswa_id,
            'dosen_id'      => $request->dosen_id,
            'matakuliah_id' => $request->matakuliah_id,
            'user_id'       => auth()->id(),
        ]);

        return redirect('/perkuliahan');
    }

    /**
     * Menampilkan form edit data perkuliahan.
     */
    public function edit($id)
    {
        $perkuliahan = Perkuliahan::findOrFail($id);
        $mahasiswa   = Mahasiswa::all();
        $dosen       = Dosen::all();
        $matakuliah  = Matakuliah::all();

        return view('perkuliahan.edit', compact('perkuliahan', 'mahasiswa', 'dosen', 'matakuliah'));
    }

    /**
     * Memperbarui data perkuliahan.
     */
    public function update(Request $request, $id)
    {
        $perkuliahan = Perkuliahan::findOrFail($id);

        $perkuliahan->update([
            'mahasiswa_id'  => $request->mahasiswa_id,
            'dosen_id'      => $request->dosen_id,
            'matakuliah_id' => $request->matakuliah_id,
        ]);

        return redirect('/perkuliahan');
    }

    /**
     * Menghapus data perkuliahan.
     */
    public function destroy($id)
    {
