      <div class="name">Asisten SIAP</div>
      <div class="role">Siap bantu pegawai &amp; atasan</div>
    </div>
    <div class="chat-body" id="chat-body">
      <div class="msg bot">Halo Rani! Ada yang bisa saya bantu terkait surat, pelatihan, atau pengumuman?</div>
    </div>
    <div class="chat-suggest">
      <span class="chip" onclick="askBot('Cara ajukan cuti')">Cara ajukan cuti</span>
      <span class="chip" onclick="askBot('Surat belum terbaca')">Surat belum terbaca</span>
      <span class="chip" onclick="askBot('Progress pelatihan saya')">Progress pelatihan</span>
    </div>
    <div class="chat-input">
      <input type="text" id="chat-text" placeholder="Tulis pertanyaan...">
      <button onclick="sendChat()">Kirim</button>
    </div>
  </div>
</div>

<script>
document.querySelectorAll('.nav-item').forEach(item=>{
  item.addEventListener('click',()=>{
    document.querySelectorAll('.nav-item').forEach(n=>n.classList.remove('active'));
    item.classList.add('active');
    const target = item.dataset.view;
    document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));
    document.getElementById('view-'+target).classList.add('active');
    document.getElementById('page-title').textContent = target==='exam' ? 'Ujian berlangsung' : 'Selamat pagi, Rani';
    document.getElementById('page-sub').textContent = target==='exam' ? 'Jangan tinggalkan halaman ujian sampai selesai' : 'Rabu, 30 Juli 2026 — Bidang Layanan e-Government';
  });
});

const fab = document.getElementById('chat-fab');
const panel = document.getElementById('chat-panel');
fab.addEventListener('click', ()=> panel.classList.toggle('open'));

const botReplies = {
  'Cara ajukan cuti':'Buka menu Surat & Dokumen, pilih "Ajukan Cuti", isi formulir lalu kirim ke atasan langsung untuk persetujuan.',
  'Surat belum terbaca':'Anda punya 3 pengumuman belum dibaca, termasuk Nota Dinas Migrasi Layanan yang perlu tindak lanjut.',
  'Progress pelatihan saya':'Progres Anda: Keamanan Data 80%, Pelayanan Publik Digital 45%, Etika ASN Digital selesai 100%.'
};

function appendMsg(text, who){
  const body = document.getElementById('chat-body');
  const div = document.createElement('div');
  div.className = 'msg ' + who;
  div.textContent = text;
  body.appendChild(div);
  body.scrollTop = body.scrollHeight;
}

function askBot(q){
  appendMsg(q, 'user');
  setTimeout(()=> appendMsg(botReplies[q] || 'Baik, saya carikan informasinya.', 'bot'), 500);
}

function sendChat(){
  const input = document.getElementById('chat-text');
  const val = input.value.trim();
  if(!val) return;
  appendMsg(val, 'user');
  input.value = '';
  setTimeout(()=> appendMsg('Pertanyaan Anda sudah saya catat. Untuk hal spesifik, saya teruskan ke admin Diskominfo ya.', 'bot'), 600);
}

let violations = 0;
function simulateTabSwitch(){
  violations++;
  document.getElementById('violation-badge').textContent = violations + ' dari 3 peringatan';
  const stage = document.getElementById('stage');
  const overlay = document.createElement('div');
  overlay.className = 'overlay';
  const isFinal = violations >= 3;
  overlay.innerHTML = `
    <div class="modal">
      <div class="icon-wrap">!</div>
      <h3 style="font-size:15px;">${isFinal ? 'Ujian dikumpulkan otomatis' : 'Aktivitas mencurigakan terdeteksi'}</h3>
      <p>${isFinal
        ? 'Anda mencapai batas 3 peringatan. Jawaban yang sudah diisi telah dikumpulkan dan ditandai untuk ditinjau atasan — tidak ada jawaban yang hilang.'
        : 'Anda terdeteksi meninggalkan halaman ujian. Pelanggaran ini tercatat waktunya. Jawaban Anda tetap aman, silakan lanjutkan dengan jujur.'}</p>
      <button class="btn btn-primary" style="width:100%;" onclick="this.closest('.overlay').remove()">${isFinal ? 'Mengerti' : 'Lanjutkan ujian'}</button>
    </div>`;
  stage.appendChild(overlay);
}
</script>
</body>
</html>
", "filename": "/home/claude/siap-mockup.html"}

