const { Document, Packer, Paragraph, TextRun, HeadingLevel, Table, TableRow, TableCell,
  WidthType, ShadingType, BorderStyle, AlignmentType, LevelFormat, convertInchesToTwip } = require("docx");

const COLOR_PRIMARY = "2C5F6D";
const COLOR_ACCENT = "9A7431";
const COLOR_MUTED = "6E838B";

const numbering = {
  config: [
    {
      reference: "bullet-list",
      levels: [
        { level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 460, hanging: 260 } } } }
      ]
    }
  ]
};

function h1(text) {
  return new Paragraph({ text, heading: HeadingLevel.HEADING_1, spacing: { before: 360, after: 160 } });
}
function h2(text) {
  return new Paragraph({ text, heading: HeadingLevel.HEADING_2, spacing: { before: 240, after: 120 } });
}
function body(text, opts = {}) {
  return new Paragraph({
    children: [new TextRun({ text, ...opts })],
    spacing: { after: 160 },
    alignment: AlignmentType.JUSTIFIED
  });
}
function bullet(text, bold) {
  return new Paragraph({
    children: bold
      ? [new TextRun({ text: bold + " — ", bold: true }), new TextRun({ text })]
      : [new TextRun({ text })],
    numbering: { reference: "bullet-list", level: 0 },
    spacing: { after: 80 }
  });
}
function cell(text, opts = {}) {
  return new TableCell({
    width: { size: opts.width || 2000, type: WidthType.DXA },
    shading: opts.header ? { type: ShadingType.CLEAR, fill: "E7F1F3" } : undefined,
    margins: { top: 100, bottom: 100, left: 120, right: 120 },
    children: [new Paragraph({
      children: [new TextRun({ text, bold: !!opts.header, size: 20 })]
    })]
  });
}
function row(cells) {
  return new TableRow({ children: cells });
}

const doc = new Document({
  numbering,
  styles: {
    default: {
      document: { run: { font: "Calibri", size: 22, color: "26343B" } }
    },
    paragraphStyles: [
      { id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 30, bold: true, color: COLOR_PRIMARY, font: "Calibri" } },
      { id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 24, bold: true, color: COLOR_ACCENT, font: "Calibri" } }
    ]
  },
  sections: [{
    properties: {
      page: { size: { width: 11906, height: 16838 }, margin: { top: 1134, bottom: 1134, left: 1134, right: 1134 } }
    },
    children: [
      new Paragraph({
        children: [new TextRun({ text: "PROPOSAL KONSEP SISTEM", bold: true, size: 44, color: COLOR_PRIMARY })],
        spacing: { before: 800, after: 100 }, alignment: AlignmentType.CENTER
      }),
      new Paragraph({
        children: [new TextRun({ text: "SIAP", bold: true, size: 60, color: COLOR_ACCENT })],
        spacing: { after: 100 }, alignment: AlignmentType.CENTER
      }),
      new Paragraph({
        children: [new TextRun({ text: "Sistem Informasi & Pembelajaran ASN", size: 26, color: COLOR_MUTED })],
        spacing: { after: 60 }, alignment: AlignmentType.CENTER
      }),
      new Paragraph({
        children: [new TextRun({ text: "Portal Internal Pegawai — Dinas Komunikasi dan Informatika Kota Sawahlunto", size: 22, color: COLOR_MUTED })],
        spacing: { after: 600 }, alignment: AlignmentType.CENTER
      }),
      new Paragraph({
        children: [new TextRun({ text: "Disusun sebagai bahan konsep Program Magang", italics: true, size: 20, color: COLOR_MUTED })],
        alignment: AlignmentType.CENTER, spacing: { after: 40 }
      }),
      new Paragraph({
        children: [new TextRun({ text: "Juli 2026", size: 20, color: COLOR_MUTED })],
        alignment: AlignmentType.CENTER
      }),
      new Paragraph({ children: [new TextRun({ text: "", break: 1 })], pageBreakBefore: true }),

      h1("1. Latar Belakang"),
      body("Di lingkungan instansi pemerintah, distribusi informasi, surat dinas, dan pelatihan pegawai umumnya masih tersebar lewat WhatsApp, email, atau dokumen fisik. Pola ini menimbulkan beberapa masalah: informasi mudah terlewat, tidak ada bukti siapa yang sudah membaca instruksi, efektivitas pelatihan sulit diukur, dan arsip dokumen rawan hilang."),
      body("SIAP diusulkan sebagai portal internal terpusat khusus pegawai dan instansi, berbeda dari LMS pendidikan pada umumnya. Fokus utamanya adalah distribusi informasi resmi, manajemen surat digital, dan pengembangan kompetensi ASN dalam satu sistem yang terintegrasi dengan data kepegawaian (SIMPEG), selaras dengan arah kebijakan Sistem Pemerintahan Berbasis Elektronik (SPBE)."),

      h1("2. Tujuan"),
      bullet("Menyediakan satu kanal resmi untuk distribusi pengumuman, surat, dan instruksi pimpinan yang dapat diaudit (siapa sudah membaca, kapan)."),
      bullet("Mendigitalkan pelatihan dan pengembangan kompetensi ASN secara terukur, bukan sekadar formalitas."),
      bullet("Mengurangi input data manual dengan menarik data jabatan pegawai langsung dari SIMPEG."),
      bullet("Mendukung target digitalisasi layanan pemerintahan daerah (SPBE)."),

      h1("3. Struktur Pengguna"),
      body("Sistem menggunakan model akses berbasis peran (role-based access control), sehingga setiap pengguna hanya melihat dan mengelola apa yang relevan dengan posisinya."),
      new Table({
        width: { size: 9500, type: WidthType.DXA },
        rows: [
          row([cell("Peran", { header: true, width: 2800 }), cell("Akses utama", { header: true, width: 6700 })]),
          row([cell("Super admin (Diskominfo)"), cell("Kelola seluruh sistem, atur hak akses, pantau integrasi SIMPEG dan log audit")]),
          row([cell("Pimpinan / Kepala Bidang"), cell("Kirim pengumuman dan surat, pantau progres bawahan, tinjau hasil ujian bermasalah")]),
          row([cell("Pegawai / Staf"), cell("Terima informasi, baca surat, ikut pelatihan dan ujian, lihat riwayat statusnya sendiri")])
        ]
      }),

      h1("4. Modul & Fitur Utama"),
      h2("4.1 Papan Informasi & Manajemen Surat Digital"),
      bullet("Unggah surat (SK, nota dinas, surat tugas) dengan kategori mendesak/rutin."),
      bullet("Tanda terima elektronik — sistem mencatat otomatis siapa dan kapan sudah membaca."),
      bullet("Arsip tersusun otomatis berdasarkan tanggal dan kategori, mudah ditelusuri kembali."),

      h2("4.2 E-Learning & Sertifikasi ASN"),
      bullet("Materi dalam bentuk video, PDF, atau slide, disertai kuis singkat untuk mengukur pemahaman."),
      bullet("Sertifikat otomatis dengan kode QR untuk verifikasi keasliannya."),
      bullet("Riwayat pelatihan bersifat portabel — tetap terbawa jika pegawai berpindah bidang."),

      h2("4.3 Sistem Ujian dengan Prinsip Kejujuran yang Adil"),
      body("Fitur ujian dirancang berlapis, agar pelanggaran integritas tetap tercatat tanpa memperlakukan peserta secara sepihak."),
      bullet("Jawaban tersimpan otomatis setiap saat, sehingga tidak ada risiko kehilangan data karena koneksi terputus."),
      bullet("Pelanggaran pertama (pindah tab/keluar layar penuh): muncul peringatan, waktunya dicatat, ujian tetap berlanjut."),
      bullet("Pelanggaran kedua: peringatan lebih tegas, notifikasi dikirim ke pengawas/atasan secara real-time."),
      bullet("Pelanggaran ketiga: ujian dikumpulkan otomatis dengan jawaban yang sudah terisi (bukan direset ke nol), lalu ditandai untuk ditinjau manual oleh atasan sebelum ada keputusan akhir."),

      h2("4.4 Asisten Chatbot Internal"),
      bullet("Bersifat sadar-peran (role-aware): jawaban untuk pegawai dan atasan bisa berbeda sesuai kebutuhan."),
      bullet("Membantu pegawai mencari informasi (status surat, progres pelatihan, cara pengajuan cuti, dsb)."),
      bullet("Membantu atasan mendapat ringkasan cepat (misalnya jumlah bawahan yang belum membaca edaran tertentu)."),
      bullet("Pertanyaan di luar kapasitasnya dieskalasikan ke admin Diskominfo, dan seluruh percakapan tercatat untuk audit."),

      h2("4.5 Integrasi Data Kepegawaian (SIMPEG)"),
      bullet("Login menggunakan akun SIMPEG (SSO) — nama, NIP, jabatan, dan unit kerja otomatis terisi tanpa input manual."),
      bullet("Perubahan rutin (kenaikan jabatan, pindah bidang internal) disinkronkan otomatis secara berkala."),
      bullet("Perubahan sensitif (pemberhentian, pindah instansi, pensiun) terdeteksi otomatis, namun akses dibatasi sementara (mode terbatas) sambil menunggu konfirmasi admin — bukan langsung dihapus penuh, untuk mengantisipasi kesalahan data atau proses serah terima tugas."),
      bullet("Setiap perubahan status tercatat pada log audit, dan pegawai dapat melihat riwayat perubahan statusnya sendiri."),

      h1("5. Arsitektur Teknis"),
      h2("5.1 Bahasa Pemrograman & Framework"),
      new Table({
        width: { size: 9500, type: WidthType.DXA },
        rows: [
          row([cell("Layer", { header: true, width: 2200 }), cell("Rekomendasi", { header: true, width: 3400 }), cell("Alasan", { header: true, width: 3900 })]),
          row([cell("Backend"), cell("Laravel (PHP) atau NestJS (Node.js)"), cell("Umum dipakai sistem pemerintahan Indonesia, dokumentasi lengkap, SDM lokal mudah ditemukan")]),
          row([cell("Frontend"), cell("React atau Vue"), cell("Komponen reusable, cocok untuk dashboard multi-modul")]),
          row([cell("Mobile"), cell("PWA terlebih dahulu"), cell("Hemat biaya di tahap awal, dapat ditingkatkan ke aplikasi native bila kebutuhan berkembang")])
        ]
      }),

      h2("5.2 Database & Integrasi SIMPEG"),
      body("Integrasi ke SIMPEG sebaiknya dilakukan melalui API (REST), bukan koneksi langsung ke basis data SIMPEG. Sistem SIAP menyimpan salinan/cache data yang relevan (nama, jabatan, unit kerja) sehingga tetap dapat berjalan meski API SIMPEG sedang tidak tersedia."),
      bullet("PostgreSQL sebagai basis data utama — umum digunakan pada sistem SPBE instansi pemerintah, kuat untuk data terstruktur seperti surat, pengguna, dan log."),
      bullet("MongoDB (opsional) untuk data pendukung yang tidak terlalu terstruktur, misalnya log percakapan chatbot."),

      h2("5.3 Hosting & Domain"),
      body("Sesuai ketentuan Kementerian Komunikasi dan Digital mengenai nama domain instansi penyelenggara negara, layanan resmi sebaiknya menggunakan subdomain \u201c.go.id\u201d milik Pemerintah Kota Sawahlunto, misalnya siap.sawahluntokota.go.id. Untuk server, arahan SPBE nasional mendorong penggunaan Pusat Data Nasional atau data center pemda yang telah terverifikasi, guna menjaga kepatuhan pengelolaan data kepegawaian."),

      h2("5.4 Keamanan"),
      new Table({
        width: { size: 9500, type: WidthType.DXA },
        rows: [
          row([cell("Aspek", { header: true, width: 2600 }), cell("Implementasi", { header: true, width: 6900 })]),
          row([cell("Autentikasi"), cell("Login melalui SSO SIMPEG (OAuth2/SAML), tanpa sistem akun terpisah")]),
          row([cell("Enkripsi"), cell("HTTPS/TLS pada seluruh koneksi, data sensitif dienkripsi (AES-256)")]),
          row([cell("Kontrol akses"), cell("Role-based access control sesuai peran pengguna")]),
          row([cell("Audit trail"), cell("Pencatatan seluruh aktivitas penting: siapa mengakses apa dan kapan")]),
          row([cell("Proteksi serangan"), cell("Validasi input, proteksi SQL injection, rate limiting")]),
          row([cell("Backup"), cell("Backup rutin dan rencana pemulihan bencana (disaster recovery)")]),
          row([cell("Kepatuhan regulasi"), cell("Selaras dengan UU Pelindungan Data Pribadi dan pedoman SPBE")])
        ]
      }),

      h1("6. Roadmap Pengembangan yang Disarankan"),
      body("Agar pengembangan realistis untuk skala tim magang/instansi, disarankan dikerjakan bertahap, bukan sekaligus. Urutan ini memprioritaskan fondasi yang paling berdampak lebih dulu."),
      new Table({
        width: { size: 9500, type: WidthType.DXA },
        rows: [
          row([cell("Fase", { header: true, width: 1600 }), cell("Fokus", { header: true, width: 7900 })]),
          row([cell("Fase 1 — Fondasi"), cell("Login SSO SIMPEG dasar, papan pengumuman, manajemen surat digital dengan tanda terima elektronik")]),
          row([cell("Fase 2 — Pembelajaran"), cell("Modul e-learning, kuis, sertifikat otomatis, dashboard monitoring progres pelatihan")]),
          row([cell("Fase 3 — Integritas & Asisten"), cell("Sistem ujian anti-kecurangan berlapis, chatbot internal role-aware")]),
          row([cell("Fase 4 — Otomasi & Penyempurnaan"), cell("Sinkronisasi otomatis status kepegawaian, dashboard analitik pimpinan, versi PWA")])
        ]
      }),
      body("Fase 1 disarankan menjadi prioritas utama karena langsung menjawab masalah paling mendasar (informasi tercecer) dengan kompleksitas teknis paling rendah, sehingga bisa jadi bukti konsep (proof of concept) yang meyakinkan sebelum modul lain dikembangkan."),

      h1("7. Manfaat"),
      bullet("Seluruh riwayat komunikasi dan surat tersimpan rapi dan mudah diaudit."),
      bullet("Menghemat kertas dan waktu distribusi informasi."),
      bullet("Pelatihan pegawai menjadi terukur, bukan sekadar formalitas."),
      bullet("Data jabatan pegawai selalu akurat karena bersumber langsung dari SIMPEG."),
      bullet("Selaras dengan target digitalisasi pemerintahan daerah (SPBE)."),

      h1("8. Penutup"),
      body("Konsep SIAP disusun sebagai portal internal yang berfokus pada kebutuhan spesifik instansi pemerintahan — bukan replikasi LMS pendidikan biasa. Dengan integrasi SIMPEG, sistem ujian yang menjunjung kejujuran secara adil, serta asisten chatbot yang membantu pegawai maupun pimpinan, SIAP diharapkan dapat menjadi contoh nyata penerapan SPBE di lingkungan Diskominfo Kota Sawahlunto.")
    ]
  }]
});

Packer.toBuffer(doc).then(buf => {
  require("fs").writeFileSync("/home/claude/Proposal-SIAP-Diskominfo-Sawahlunto.docx", buf);
  console.log("done");
});

