<?php

namespace App\Http\Controllers;

use App\Models\Training;
use App\Models\TrainingProgress;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Auth;
use Illuminate\Support\Str;

class TrainingController extends Controller
{
    public function index()
    {
        $user = Auth::user();
        $trainings = Training::with('creator')->latest()->get();

        // Supaya di view bisa langsung tau status progres tiap pelatihan tanpa query berulang.
        $progresses = TrainingProgress::where('user_id', $user->id)
            ->pluck('status', 'training_id');

        return view('trainings.index', compact('trainings', 'progresses'));
    }

    public function show(Training $training)
    {
        $user = Auth::user();
        $progress = $training->progressFor($user);

        return view('trainings.show', compact('training', 'progress'));
    }

    // Dipanggil saat pegawai klik "Mulai pelatihan".
    public function start(Training $training)
    {
        TrainingProgress::firstOrCreate(
            ['training_id' => $training->id, 'user_id' => Auth::id()],
            ['status' => 'sedang_berjalan']
        );

        return redirect()->route('trainings.show', $training)->with('status', 'Pelatihan dimulai.');
    }

    // Dipanggil saat pegawai klik "Tandai selesai" (di versi selanjutnya, ini bisa dipicu otomatis setelah lulus kuis).
    public function complete(Training $training)
    {
        $progress = TrainingProgress::firstOrCreate(
            ['training_id' => $training->id, 'user_id' => Auth::id()],
            ['status' => 'sedang_berjalan']
        );

        $progress->update([
            'status' => 'selesai',
            'completed_at' => now(),
            // Kode unik buat verifikasi sertifikat, misalnya lewat QR nanti.
            'certificate_code' => $progress->certificate_code ?? strtoupper(Str::random(10)),
        ]);

        return redirect()->route('trainings.show', $training)->with('status', 'Selamat, pelatihan selesai! Sertifikat sudah diterbitkan.');
    }

    public function create()
    {
        abort_unless(in_array(Auth::user()->role, ['atasan', 'admin']), 403);

        return view('trainings.create');
    }

    public function store(Request $request)
    {
        abort_unless(in_array(Auth::user()->role, ['atasan', 'admin']), 403);

        $validated = $request->validate([
            'title' => 'required|string|max:255',
            'description' => 'nullable|string',
        ]);

        Training::create([
            ...$validated,
            'created_by' => Auth::id(),
        ]);

        return redirect()->route('trainings.index')->with('status', 'Pelatihan berhasil dibuat.');
    }
}
```

Catatan logikanya:
- `certificate_code` cuma dibuat sekali (`?? ...`) — kalau pegawai klik "selesai" berkali-kali, kodenya nggak berubah-ubah.
- `firstOrCreate` di `complete()` jaga-jaga kalau pegawai belum sempat klik "mulai" tapi langsung ada tombol "selesai" (nggak akan error).

